pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint48 depositCount) public {
        // Keep deposit amount reasonable and number of deposits bounded
        vm.assume(depositAmount > 0);
        vm.assume(depositCount > 0);
        bound(depositAmount, 1, 1 ether);
        bound(depositCount, 1, 10);

        // Fund the contract through multiple deposits
        address donor = makeAddr("donor");
        vm.deal(donor, depositAmount * depositCount);
        vm.startPrank(donor);
        for (uint48 i = 0; i < depositCount; i++) {
            (bool ok,) = address(c).call{value: depositAmount}("");
            require(ok, "deposit failed");
        }
        vm.stopPrank();

        // Record balance before withdrawAll
        uint256 balanceBefore = address(c).balance;
        vm.assume(balanceBefore > 0);

        // Owner withdraws all
        address owner = c.owner();
        vm.prank(owner);
        bool success;
        try c.withdrawAll() { success = true; } catch { success = false; }

        // Rule: if withdrawAll succeeds, the contract balance must become zero
        assertTrue(!success || address(c).balance == 0);
    }
}

