pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialBalance, uint256 donation) public {
        // Bound initialBalance to avoid overflow when summing; keep domain wide
        initialBalance = bound(initialBalance, 1, type(uint256).max / 2);
        donation = bound(donation, 0, type(uint256).max - initialBalance);
        // Ensure contract has enough balance initially
        vm.deal(address(c), initialBalance);
        // Optionally receive another donation via fallback to increase state
        if (donation > 0) {
            vm.deal(address(this), donation);
            vm.prank(address(this));
            (bool sent,) = address(c).call{value: donation}("");
            require(sent);
        }
        uint256 contractBalanceBefore = address(c).balance;
        address owner = c.owner();
        uint256 ownerBalanceBefore = owner.balance;
        // Owner calls withdrawAll
        vm.prank(owner);
        c.withdrawAll();
        uint256 ownerBalanceAfter = owner.balance;
        // Assert: owner's balance must increase by exactly the contract's balance before the call
        assertTrue(ownerBalanceAfter == ownerBalanceBefore + contractBalanceBefore);
    }
}

